local startFloatStart = assert(waterDrownService:find('function WaterDrownService:_startFloat', 1, true))
local updateFloatsStart = assert(waterDrownService:find('function WaterDrownService:_updateFloats', startFloatStart, true))
local startFloatSource = waterDrownService:sub(startFloatStart, updateFloatsStart - 1)
assert(startFloatSource:find('self._Random:NextNumber()', 1, true), "Float orientation must be chosen when floating starts")
assert(not waterDrownService:sub(updateFloatsStart):find('self._Random:NextNumber()', 1, true), "Float orientation must not be randomized every heartbeat")
assert(waterDrownService:find('state.orientation:Destroy()', 1, true), "Stopping float must destroy the orientation constraint")
